<script setup lang="ts">import { computed, onMounted, ref } from 'vue';import { api } from '../api';import { ElMessage } from 'element-plus';const rows=ref<any[]>([]),unread=computed(()=>rows.value.filter(n=>!n.read).length);async function load(){rows.value=await api.notifications()}onMounted(load);async function read(id:number){await api.read(id);load()}async function readAll(){await api.readAll();ElMessage.success('已全部标记为已读');load()}</script>
<template><div class="page"><div class="page-header"><div><h1 class="page-title">通知中心</h1><p>未读 {{unread}} 条</p></div><el-button v-if="unread" @click="readAll">全部已读</el-button></div><section class="card"><el-empty v-if="!rows.length" description="暂无通知"/><el-timeline v-else><el-timeline-item v-for="n in rows" :key="n.id" :type="n.read?'info':'primary'" :timestamp="n.createdAt"><b>{{n.title}}</b><p>{{n.content}}</p><el-button v-if="!n.read" size="small" @click="read(n.id)">标记已读</el-button></el-timeline-item></el-timeline></section></div></template>
